# Hindi / Gujarati text for Economics Ch 1 lesson, sections 4-5.
TEXT_B = {
 "s4.thm.title": ("मानव विकास रिपोर्ट और धारणीय विकास", "માનવ વિકાસ અહેવાલ અને ટકાઉ વિકાસ"),
 "s4.thm.body": (
  "**मानव विकास रिपोर्ट:** जब हम समझ जाते हैं कि आय ज़रूरी होने पर भी पर्याप्त मापदंड नहीं, तो हम दूसरे मापदंड ढूँढ़ते हैं। **UNDP (संयुक्त राष्ट्र विकास कार्यक्रम)** द्वारा प्रकाशित **मानव विकास रिपोर्ट** देशों की तुलना लोगों के **शैक्षिक स्तर**, उनकी **स्वास्थ्य स्थिति** और **प्रतिव्यक्ति आय** के आधार पर करती है।\n"
  "- **जन्म के समय संभावित आयु**, जैसा नाम से स्पष्ट है, जन्म के समय किसी व्यक्ति की औसत संभावित आयु को दर्शाती है।\n"
  "- तीन स्तरों के लिए **सकल नामांकन अनुपात** का अर्थ है प्राथमिक स्कूल, माध्यमिक स्कूल और उससे आगे उच्च शिक्षा में नामांकन का अनुपात।\n"
  "- मानव विकास रिपोर्ट में तुलना के लिए सभी देशों की **प्रतिव्यक्ति आय डॉलर** में निकाली जाती है, इस तरह कि हर डॉलर से किसी भी देश में बराबर वस्तुएँ और सेवाएँ ख़रीदी जा सकें (**क्रय शक्ति समता**)।\n"
  "- मानव विकास रिपोर्ट 2019 (NCERT के अनुसार) में **श्रीलंका** (रैंक **71**) मानव विकास में **भारत** (रैंक **129**) से बहुत आगे था, हालाँकि श्रीलंका बहुत छोटा देश है। भारत के पड़ोसी बांग्लादेश, नेपाल, म्यांमार और पाकिस्तान भारत से नीचे या आसपास थे।\n\n"
  "**विकास की धारणीयता:** विकास भावी पीढ़ियों की क़ीमत पर नहीं होना चाहिए। वैज्ञानिक चेतावनी देते रहे हैं कि विकास का वर्तमान प्रकार और स्तर **धारणीय नहीं** है।\n"
  "- **भूमिगत जल:** हाल के प्रमाण बताते हैं कि देश में भूमिगत जल के **अति-उपयोग** का गंभीर ख़तरा है। भूमिगत जल **नवीकरणीय संसाधन** का उदाहरण है: प्रकृति इसकी पूर्ति करती है, जैसे फ़सलों और पौधों के मामले में। पर इन संसाधनों का भी अति-उपयोग हो सकता है: भूमिगत जल के मामले में, अगर हम वर्षा से होने वाली पूर्ति से ज़्यादा इस्तेमाल करें, तो यह अति-उपयोग है।\n"
  "- **गैर-नवीकरणीय संसाधन** वे हैं जो कुछ वर्षों के इस्तेमाल के बाद ख़त्म हो जाएँगे। पृथ्वी पर इनका सीमित भंडार है जिसकी पूर्ति नहीं हो सकती। हम नए संसाधन खोजते हैं जिससे भंडार बढ़ता है, पर समय के साथ ये भी ख़त्म हो जाएँगे। **कच्चा तेल** इसका उदाहरण है: अगर दुनिया इसे वर्तमान दर से निकालती रही, तो भंडार कुछ ही वर्ष चलेंगे। भारत को अपना बहुत-सा तेल आयात करना पड़ता है, जो उसे असुरक्षित बनाता है।\n"
  "- **पर्यावरण का क्षरण** किसी एक राष्ट्र या राज्य तक सीमित नहीं। ऐसे मुद्दे अब **क्षेत्रीय या राष्ट्रीय नहीं** रहे; हमारा भविष्य आपस में जुड़ा है। **विकास की धारणीयता** ज्ञान का एक अपेक्षाकृत नया क्षेत्र है जिसमें वैज्ञानिक, अर्थशास्त्री, दार्शनिक और दूसरे सामाजिक वैज्ञानिक मिलकर काम कर रहे हैं।\n"
  "- सामान्य तौर पर विकास या प्रगति का प्रश्न हमेशा बना रहता है। हर समय, समाज के सदस्य और व्यक्ति के रूप में हमें पूछना होता है कि **हम कहाँ जाना चाहते हैं, क्या बनना चाहते हैं और हमारे लक्ष्य क्या हैं**।",
  "**માનવ વિકાસ અહેવાલ:** જ્યારે આપણે સમજીએ કે આવક મહત્ત્વની હોવા છતાં પૂરતો માપદંડ નથી, ત્યારે આપણે બીજા માપદંડો શોધીએ છીએ. **UNDP (સંયુક્ત રાષ્ટ્ર વિકાસ કાર્યક્રમ)** દ્વારા પ્રકાશિત **માનવ વિકાસ અહેવાલ** દેશોની સરખામણી લોકોના **શૈક્ષણિક સ્તર**, તેમની **આરોગ્ય સ્થિતિ** અને **માથાદીઠ આવક**ના આધારે કરે છે.\n"
  "- **જન્મ સમયે અપેક્ષિત આયુષ્ય**, નામ પ્રમાણે, જન્મ સમયે વ્યક્તિના સરેરાશ અપેક્ષિત આયુષ્યને દર્શાવે છે.\n"
  "- ત્રણ સ્તર માટે **કુલ નોંધણી પ્રમાણ**નો અર્થ છે પ્રાથમિક શાળા, માધ્યમિક શાળા અને તે પછીના ઉચ્ચ શિક્ષણમાં નોંધણીનું પ્રમાણ.\n"
  "- માનવ વિકાસ અહેવાલમાં સરખામણી માટે બધા દેશોની **માથાદીઠ આવક ડૉલર**માં ગણાય છે, એ રીતે કે દરેક ડૉલરથી કોઈ પણ દેશમાં સરખી વસ્તુઓ અને સેવાઓ ખરીદી શકાય (**ખરીદશક્તિ સમાનતા**).\n"
  "- માનવ વિકાસ અહેવાલ 2019 (NCERT મુજબ)માં **શ્રીલંકા** (ક્રમ **71**) માનવ વિકાસમાં **ભારત** (ક્રમ **129**) કરતાં ઘણું આગળ હતું, જોકે શ્રીલંકા ઘણો નાનો દેશ છે. ભારતના પડોશીઓ બાંગ્લાદેશ, નેપાળ, મ્યાનમાર અને પાકિસ્તાન ભારતથી નીચે કે આસપાસ હતા.\n\n"
  "**વિકાસનું ટકાઉપણું:** વિકાસ ભાવિ પેઢીઓના ભોગે ન થવો જોઈએ. વૈજ્ઞાનિકો ચેતવણી આપતા રહ્યા છે કે વિકાસનો વર્તમાન પ્રકાર અને સ્તર **ટકાઉ નથી**.\n"
  "- **ભૂગર્ભજળ:** તાજેતરના પુરાવા બતાવે છે કે દેશમાં ભૂગર્ભજળના **અતિ ઉપયોગ**નો ગંભીર ખતરો છે. ભૂગર્ભજળ **પુનઃપ્રાપ્ય સંસાધન**નું ઉદાહરણ છે: કુદરત તેની પૂર્તિ કરે છે, જેમ પાક અને છોડના કિસ્સામાં. પણ આ સંસાધનોનો પણ અતિ ઉપયોગ થઈ શકે: ભૂગર્ભજળના કિસ્સામાં, જો આપણે વરસાદથી થતી પૂર્તિ કરતાં વધુ વાપરીએ, તો તે અતિ ઉપયોગ છે.\n"
  "- **અપુનઃપ્રાપ્ય સંસાધનો** એ છે જે થોડાં વર્ષોના ઉપયોગ પછી ખલાસ થઈ જશે. પૃથ્વી પર તેનો મર્યાદિત જથ્થો છે જેની પૂર્તિ થઈ શકતી નથી. આપણે નવાં સંસાધનો શોધીએ છીએ જેથી જથ્થો વધે છે, પણ સમય જતાં તે પણ ખલાસ થશે. **ખનિજ તેલ** તેનું ઉદાહરણ છે: જો દુનિયા તેને વર્તમાન દરે કાઢતી રહે, તો જથ્થો થોડાં જ વર્ષ ચાલશે. ભારતે પોતાનું ઘણું તેલ આયાત કરવું પડે છે, જે તેને નબળું બનાવે છે.\n"
  "- **પર્યાવરણનો હ્રાસ** કોઈ એક રાષ્ટ્ર કે રાજ્ય પૂરતો મર્યાદિત નથી. આવા પ્રશ્નો હવે **પ્રાદેશિક કે રાષ્ટ્રીય રહ્યા નથી**; આપણું ભવિષ્ય એકબીજા સાથે જોડાયેલું છે. **વિકાસનું ટકાઉપણું** જ્ઞાનનું પ્રમાણમાં નવું ક્ષેત્ર છે જેમાં વૈજ્ઞાનિકો, અર્થશાસ્ત્રીઓ, ફિલસૂફો અને બીજા સમાજવૈજ્ઞાનિકો સાથે મળીને કામ કરે છે.\n"
  "- સામાન્ય રીતે વિકાસ કે પ્રગતિનો પ્રશ્ન હંમેશાં રહે છે. દરેક સમયે, સમાજના સભ્ય અને વ્યક્તિ તરીકે આપણે પૂછવું પડે કે **આપણે ક્યાં જવા માગીએ છીએ, શું બનવા માગીએ છીએ અને આપણાં લક્ષ્યો શાં છે**."),
 "s5.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s5.memory.body": (
  "- **प्रतिव्यक्ति आय = कुल आय ÷ जनसंख्या।**\n- **विश्व बैंक (WDR 2019): समृद्ध ≥ USD 12,056; निम्न ≤ USD 955; भारत = USD 1,820 (निम्न मध्य)।**\n"
  "- **UNDP HDI = \"स्वा-शि-आ\"**: स्वास्थ्य (संभावित आयु), शिक्षा (साक्षरता, नामांकन), आय (प्रतिव्यक्ति, PPP डॉलर में)।\n"
  "- **IMR = 1 वर्ष से पहले मृत्यु प्रति 1000 जीवित जन्म; साक्षरता = 7+ वर्ष; उपस्थिति = 14–15 वर्ष।**\n"
  "- **केरल बनाम हरियाणा: \"केरल बच्चों को बचाता है\"**: आय कम, पर IMR 7 बनाम 30।\n- **नवीकरणीय = पूर्ति होती है (भूमिगत जल); गैर-नवीकरणीय = पूर्ति नहीं (कच्चा तेल)।**",
  "- **માથાદીઠ આવક = કુલ આવક ÷ વસ્તી.**\n- **વિશ્વ બૅન્ક (WDR 2019): સમૃદ્ધ ≥ USD 12,056; ઓછી ≤ USD 955; ભારત = USD 1,820 (નિમ્ન મધ્યમ).**\n"
  "- **UNDP HDI = \"આ-શિ-આ\"**: આરોગ્ય (અપેક્ષિત આયુષ્ય), શિક્ષણ (સાક્ષરતા, નોંધણી), આવક (માથાદીઠ, PPP ડૉલરમાં).\n"
  "- **IMR = 1 વર્ષ પહેલાં મૃત્યુ દર 1000 જીવિત જન્મે; સાક્ષરતા = 7+ વર્ષ; હાજરી = 14–15 વર્ષ.**\n"
  "- **કેરળ સામે હરિયાણા: \"કેરળ બાળકોને બચાવે\"**: આવક ઓછી, પણ IMR 7 સામે 30.\n- **પુનઃપ્રાપ્ય = પૂર્તિ થાય (ભૂગર્ભજળ); અપુનઃપ્રાપ્ય = પૂર્તિ ન થાય (ખનિજ તેલ).**"),
 "s5.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s5.mistakes.body": (
  "1. यह कहना कि सबके विकास के लक्ष्य एक हैं: लक्ष्य **अलग और परस्पर विरोधी** भी हो सकते हैं।\n2. कुल आय को सबसे अच्छी तुलना मानना: जनसंख्या अलग होने से हम **औसत (प्रतिव्यक्ति) आय** इस्तेमाल करते हैं।\n"
  "3. भूल जाना कि औसत **असमानताएँ छिपाते** हैं।\n4. यह कहना कि केरल की प्रतिव्यक्ति आय सबसे ज़्यादा है: तीनों में **हरियाणा** की सबसे ज़्यादा है; केरल स्वास्थ्य और शिक्षा में आगे है।\n"
  "5. विश्व बैंक और UNDP को मिलाना: विश्व बैंक **प्रतिव्यक्ति आय** इस्तेमाल करता है; UNDP **स्वास्थ्य, शिक्षा और आय**।\n6. भूमिगत जल को गैर-नवीकरणीय कहना: यह **नवीकरणीय** है, पर इसका अति-उपयोग हो सकता है।",
  "1. કહેવું કે બધાનાં વિકાસનાં લક્ષ્યો સરખાં છે: લક્ષ્યો **જુદાં અને પરસ્પર વિરોધી** પણ હોઈ શકે.\n2. કુલ આવકને શ્રેષ્ઠ સરખામણી ગણવી: વસ્તી જુદી હોવાથી આપણે **સરેરાશ (માથાદીઠ) આવક** વાપરીએ છીએ.\n"
  "3. ભૂલી જવું કે સરેરાશ **અસમાનતાઓ છુપાવે** છે.\n4. કહેવું કે કેરળની માથાદીઠ આવક સૌથી વધુ છે: ત્રણેયમાં **હરિયાણા**ની સૌથી વધુ છે; કેરળ આરોગ્ય અને શિક્ષણમાં આગળ છે.\n"
  "5. વિશ્વ બૅન્ક અને UNDPને ભેળવવા: વિશ્વ બૅન્ક **માથાદીઠ આવક** વાપરે છે; UNDP **આરોગ્ય, શિક્ષણ અને આવક**.\n6. ભૂગર્ભજળને અપુનઃપ્રાપ્ય કહેવું: તે **પુનઃપ્રાપ્ય** છે, પણ તેનો અતિ ઉપયોગ થઈ શકે."),
 "s5.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s5.tip.body": (
  "पाँच छात्रों को काल्पनिक आय दीजिए (जैसे Rs 500, 500, 500, 500 और 48,000)। कक्षा से औसत निकालने को कहिए, फिर पूछिए: क्या औसत इन पाँच लोगों को ठीक से दर्शाता है? यही अभ्यास उतने ही औसत वाली लगभग बराबर पाँच आयों से दोहराइए।",
  "પાંચ વિદ્યાર્થીઓને કાલ્પનિક આવક આપો (જેમ કે Rs 500, 500, 500, 500 અને 48,000). વર્ગને સરેરાશ કાઢવા કહો, પછી પૂછો: શું સરેરાશ આ પાંચ લોકોને બરાબર દર્શાવે છે? આ જ અભ્યાસ એટલી જ સરેરાશવાળી લગભગ સરખી પાંચ આવકો સાથે કરો."),
 "s5.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s5.reflection.body": (
  "अपने लिए विकास के तीन लक्ष्य और अपने इलाक़े के लिए तीन लक्ष्य लिखिए। इनमें से कौन-से आय के बारे में हैं, और कौन-से सुरक्षा, सम्मान या साफ़ हवा जैसी ग़ैर-भौतिक चीज़ों के बारे में?",
  "પોતાના માટે વિકાસનાં ત્રણ લક્ષ્યો અને પોતાના વિસ્તાર માટે ત્રણ લક્ષ્યો લખો. તેમાંથી કયાં આવક વિશે છે, અને કયાં સલામતી, આદર કે સ્વચ્છ હવા જેવી બિનભૌતિક બાબતો વિશે?"),
 "s5.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s5.connection.body": (
  "- **अध्याय 2 (भारतीय अर्थव्यवस्था के क्षेत्रक):** रोज़गार, आय और नौकरियाँ।\n- **भूगोल अध्याय 1 (संसाधन एवं विकास):** संसाधनों का धारणीय उपयोग।\n"
  "- **राजनीति विज्ञान अध्याय 5 (लोकतंत्र के परिणाम):** आर्थिक संवृद्धि और असमानता।",
  "- **પ્રકરણ 2 (ભારતીય અર્થતંત્રનાં ક્ષેત્રો):** રોજગાર, આવક અને નોકરીઓ.\n- **ભૂગોળ પ્રકરણ 1 (સંસાધનો અને વિકાસ):** સંસાધનોનો ટકાઉ ઉપયોગ.\n"
  "- **રાજ્યશાસ્ત્ર પ્રકરણ 5 (લોકશાહીનાં પરિણામો):** આર્થિક વૃદ્ધિ અને અસમાનતા."),
 "s5.mastery.title": ("महारत चुनौती", "નિપુણતા પડકાર"),
 "s5.mastery.body": (
  "'प्रतिव्यक्ति आय बिल्कुल उपयोगी मापदंड नहीं है।' क्या आप सहमत हैं? लगभग 120 शब्दों में उत्तर दीजिए।\n\n"
  "**आदर्श उत्तर:** मैं पूरी तरह सहमत नहीं। प्रतिव्यक्ति आय उपयोगी है: कुल आय को जनसंख्या से भाग देकर हम अलग-अलग आकार के देशों की तुलना कर सकते हैं, और विश्व बैंक इसी से देशों को समृद्ध, मध्य आय या निम्न आय में बाँटता है। "
  "पर इसकी सीमाएँ हैं। औसत होने से यह असमानताएँ छिपाती है: एक ही औसत वाले दो देशों में आय का बँटवारा बहुत अलग हो सकता है। यह ग़ैर-भौतिक लक्ष्यों और सार्वजनिक सुविधाओं की भी अनदेखी करती है। "
  "केरल की प्रतिव्यक्ति आय हरियाणा से कम है, फिर भी अच्छी स्वास्थ्य और शिक्षा सुविधाओं के कारण उसकी शिशु मृत्यु दर बहुत कम और साक्षरता तथा उपस्थिति ज़्यादा है। "
  "इसलिए प्रतिव्यक्ति आय का इस्तेमाल दूसरे सूचकों के साथ होना चाहिए, जैसे UNDP के मानव विकास सूचकांक में।",
  "'માથાદીઠ આવક બિલકુલ ઉપયોગી માપદંડ નથી.' શું તમે સંમત છો? આશરે 120 શબ્દોમાં જવાબ આપો.\n\n"
  "**આદર્શ જવાબ:** હું સંપૂર્ણ સંમત નથી. માથાદીઠ આવક ઉપયોગી છે: કુલ આવકને વસ્તીથી ભાગીને આપણે જુદા જુદા કદના દેશોની સરખામણી કરી શકીએ, અને વિશ્વ બૅન્ક તેના આધારે દેશોને સમૃદ્ધ, મધ્યમ આવક કે ઓછી આવકમાં વહેંચે છે. "
  "પણ તેની મર્યાદાઓ છે. સરેરાશ હોવાથી તે અસમાનતાઓ છુપાવે છે: એક જ સરેરાશવાળા બે દેશોમાં આવકની વહેંચણી ઘણી જુદી હોઈ શકે. તે બિનભૌતિક લક્ષ્યો અને જાહેર સુવિધાઓની પણ અવગણના કરે છે. "
  "કેરળની માથાદીઠ આવક હરિયાણા કરતાં ઓછી છે, છતાં સારી આરોગ્ય અને શૈક્ષણિક સુવિધાઓને કારણે તેનો બાળ મૃત્યુ દર ઘણો ઓછો અને સાક્ષરતા તથા હાજરી વધુ છે. "
  "તેથી માથાદીઠ આવકનો ઉપયોગ બીજા સૂચકો સાથે થવો જોઈએ, જેમ કે UNDPના માનવ વિકાસ આંકમાં."),
 "s5.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s5.summary.body": (
  "- अलग-अलग लोगों के विकास के लक्ष्य अलग, और कभी-कभी परस्पर विरोधी, होते हैं; लोग आय के साथ बराबरी, स्वतंत्रता, सुरक्षा और सम्मान भी चाहते हैं।\n"
  "- देशों की तुलना प्रतिव्यक्ति (औसत) आय से होती है; विश्व बैंक इसी से वर्गीकरण करता है, और भारत निम्न मध्य आय समूह में है।\n"
  "- औसत असमानताएँ छिपाते हैं, और आय सार्वजनिक सुविधाओं तक पहुँच नहीं दिखाती।\n"
  "- हरियाणा से कम प्रतिव्यक्ति आय वाला केरल शिशु मृत्यु दर, साक्षरता और उपस्थिति में बहुत आगे है।\n"
  "- UNDP की मानव विकास रिपोर्ट देशों की तुलना शिक्षा, स्वास्थ्य और आय पर करती है; श्रीलंका भारत से बहुत ऊपर है।\n"
  "- विकास धारणीय होना चाहिए: भूमिगत जल का अति-उपयोग हो रहा है और कच्चा तेल ख़त्म हो रहा है।",
  "- જુદા જુદા લોકોનાં વિકાસનાં લક્ષ્યો જુદાં, અને ક્યારેક પરસ્પર વિરોધી, હોય છે; લોકો આવક સાથે સમાનતા, સ્વતંત્રતા, સલામતી અને આદર પણ ઇચ્છે છે.\n"
  "- દેશોની સરખામણી માથાદીઠ (સરેરાશ) આવકથી થાય છે; વિશ્વ બૅન્ક તેના આધારે વર્ગીકરણ કરે છે, અને ભારત નિમ્ન મધ્યમ આવક જૂથમાં છે.\n"
  "- સરેરાશ અસમાનતાઓ છુપાવે છે, અને આવક જાહેર સુવિધાઓ સુધીની પહોંચ દર્શાવતી નથી.\n"
  "- હરિયાણા કરતાં ઓછી માથાદીઠ આવકવાળું કેરળ બાળ મૃત્યુ દર, સાક્ષરતા અને હાજરીમાં ઘણું આગળ છે.\n"
  "- UNDPનો માનવ વિકાસ અહેવાલ દેશોની સરખામણી શિક્ષણ, આરોગ્ય અને આવક પર કરે છે; શ્રીલંકા ભારત કરતાં ઘણું ઉપર છે.\n"
  "- વિકાસ ટકાઉ હોવો જોઈએ: ભૂગર્ભજળનો અતિ ઉપયોગ થાય છે અને ખનિજ તેલ ખલાસ થઈ રહ્યું છે."),
 "s5.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટેની ટિપ્સ"),
 "s5.examtips.body": (
  "- 2025-26 के प्रतिदर्श प्रश्न-पत्र में प्रतिव्यक्ति आय की सीमा पूछी गई (यह कल्याण का मूल अंदाज़ा देती है पर आय की असमानता छिपाती है; उत्तर C), और कल्याण के लिए सार्वजनिक सेवाओं (स्वास्थ्य, शिक्षा, स्वच्छता और साफ़ पानी, बुनियादी ढाँचा) की उपयोगिता (3 अंक)।\n"
  "- 3/5 अंक के पसंदीदा प्रश्न: अलग-अलग लक्ष्य, प्रतिव्यक्ति आय की सीमाएँ, केरल और हरियाणा की तुलना, विश्व बैंक बनाम UNDP के मापदंड, धारणीयता।\n"
  "- शिशु मृत्यु दर, साक्षरता दर और निवल उपस्थिति अनुपात की परिभाषाएँ ठीक-ठीक याद करें।",
  "- 2025-26ના નમૂનાના પ્રશ્નપત્રમાં માથાદીઠ આવકની મર્યાદા પુછાઈ (તે કલ્યાણનો મૂળભૂત ખ્યાલ આપે છે પણ આવકની અસમાનતા છુપાવે છે; જવાબ C), અને કલ્યાણ માટે જાહેર સેવાઓ (આરોગ્ય, શિક્ષણ, સ્વચ્છતા અને શુદ્ધ પાણી, માળખાકીય સુવિધાઓ)ની ઉપયોગિતા (3 ગુણ).\n"
  "- 3/5 ગુણના પ્રિય પ્રશ્નો: જુદાં જુદાં લક્ષ્યો, માથાદીઠ આવકની મર્યાદાઓ, કેરળ અને હરિયાણાની સરખામણી, વિશ્વ બૅન્ક સામે UNDPના માપદંડો, ટકાઉપણું.\n"
  "- બાળ મૃત્યુ દર, સાક્ષરતા દર અને ચોખ્ખા હાજરી પ્રમાણની વ્યાખ્યાઓ બરાબર યાદ કરો."),
 "s5.flash1.front": ("प्रतिव्यक्ति आय क्या है?", "માથાદીઠ આવક શું છે?"),
 "s5.flash1.back": ("किसी देश की कुल आय को उसकी कुल जनसंख्या से भाग देने पर मिली आय; इसे औसत आय भी कहते हैं।", "કોઈ દેશની કુલ આવકને તેની કુલ વસ્તીથી ભાગતાં મળતી આવક; તેને સરેરાશ આવક પણ કહે છે."),
 "s5.flash2.front": ("शिशु मृत्यु दर क्या है?", "બાળ મૃત્યુ દર શું છે?"),
 "s5.flash2.back": ("किसी वर्ष पैदा हुए 1000 जीवित बच्चों में से एक वर्ष की आयु से पहले मरने वाले बच्चों का अनुपात।", "કોઈ વર્ષમાં જન્મેલાં 1000 જીવિત બાળકોમાંથી એક વર્ષની ઉંમર પહેલાં મૃત્યુ પામતાં બાળકોનું પ્રમાણ."),
 "s5.flash3.front": ("UNDP की मानव विकास रिपोर्ट देशों की तुलना किस आधार पर करती है?", "UNDPનો માનવ વિકાસ અહેવાલ દેશોની સરખામણી શાના આધારે કરે છે?"),
 "s5.flash3.back": ("शैक्षिक स्तर, स्वास्थ्य स्थिति और प्रतिव्यक्ति आय।", "શૈક્ષણિક સ્તર, આરોગ્ય સ્થિતિ અને માથાદીઠ આવક."),
 "s5.flash4.front": ("धारणीय विकास क्या है?", "ટકાઉ વિકાસ શું છે?"),
 "s5.flash4.back": ("ऐसा विकास जो भावी पीढ़ियों के लिए संसाधन ख़त्म किए या पर्यावरण बिगाड़े बिना वर्तमान ज़रूरतें पूरी करे।", "એવો વિકાસ જે ભાવિ પેઢીઓ માટે સંસાધનો ખલાસ કર્યા વિના કે પર્યાવરણ બગાડ્યા વિના વર્તમાન જરૂરિયાતો પૂરી કરે."),
}
